"use client";

import * as React from "react";
import { Copy, Plus, Trash2 } from "lucide-react";
import { ConfirmAction } from "./confirm-action";
import { NumberRoll } from "./number-roll";
import { RelativeTime, type DateLike } from "./relative-time";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import {
  DeliveryList,
  StatusChip,
  type WebhookDelivery,
} from "./webhook-deliveries";
import { WebhookWire } from "./webhook-wire";

/* ─────────────────────────────────────────────────────────
 * WEBHOOKS: Settings → Webhooks, done properly
 *
 *   add       "Add endpoint" opens the form above the list: the
 *             URL and the events it wants. The new endpoint
 *             fades in on top, already open on "Send test"
 *   test      the test is drawn as the request it is: a bead
 *             runs the thin line to the endpoint, waits while it
 *             answers, and comes home in the answer's colour;
 *             "200 OK in 182 ms" rolls in, and the delivery
 *             lands on top of the list
 *   inspect   every delivery opens into its request and
 *             response; Redeliver sends it again and the new
 *             attempt arrives on top
 *   secret    the signing secret stays dots until you reveal
 *             it, then copies with a drawn check
 *   pause     Enabled is a switch that saves itself; Delete
 *             stretches the bin into a confirm and folds the
 *             endpoint away
 *
 * Endpoints and deliveries are plain records; every action is
 * one async function, so it fits Svix, Hookdeck or your own
 * queue.
 * ───────────────────────────────────────────────────────── */

export type { WebhookDelivery, DateLike };

export interface WebhookEndpoint {
  id: string;
  url: string;
  /** The event types it receives. */
  events: string[];
  enabled?: boolean;
  /** Shown on the collapsed row. */
  lastDelivery?: { status: number | null; at: DateLike } | null;
}

export interface WebhookEventType {
  value: string;
  description?: string;
}

export interface WebhooksProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange" | "onToggle"
> {
  value?: WebhookEndpoint[];
  defaultValue?: WebhookEndpoint[];
  onValueChange?: (endpoints: WebhookEndpoint[]) => void;
  /** Event types an endpoint can subscribe to. */
  events: WebhookEventType[];
  /** Creates an endpoint. Throw to keep the form and say why. */
  onCreate: (input: {
    url: string;
    events: string[];
  }) => Promise<WebhookEndpoint>;
  /** Sends a test event and returns the delivery it made. */
  onTest: (
    endpoint: WebhookEndpoint,
    event: string,
  ) => Promise<WebhookDelivery>;
  /** Recent deliveries, newest first; pass the oldest one shown to page back. An empty list means there are no more. */
  loadDeliveries?: (
    endpoint: WebhookEndpoint,
    before?: WebhookDelivery,
  ) => Promise<WebhookDelivery[]>;
  onRedeliver?: (
    delivery: WebhookDelivery,
    endpoint: WebhookEndpoint,
  ) => Promise<WebhookDelivery>;
  onRevealSecret?: (endpoint: WebhookEndpoint) => Promise<string>;
  /** Turns an endpoint on or off. Throw to put the switch back. */
  onToggle?: (endpoint: WebhookEndpoint, enabled: boolean) => Promise<unknown>;
  onDelete?: (endpoint: WebhookEndpoint) => Promise<unknown>;
  /** Your app's name, at the near end of the test's wire. */
  appName?: string;
  title?: string;
  description?: string;
}

type Draft = {
  url: string;
  events: string[];
  status: ActionStatus;
  error: string | null;
};
type Log = {
  items: WebhookDelivery[];
  loading: boolean;
  more: boolean;
  loaded: boolean;
};

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const NONE: WebhookEndpoint[] = [];
const SHAKE = [
  { transform: "none" },
  { transform: "translateX(-4px)" },
  { transform: "translateX(4px)" },
  { transform: "translateX(-2px)" },
  { transform: "none" },
];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const message = (e: unknown, fallback: string) =>
  e instanceof Error && e.message ? e.message : fallback;
const split = (url: string) => {
  try {
    const u = new URL(url);
    return {
      host: u.host,
      path: `${u.pathname === "/" ? "" : u.pathname}${u.search}`,
    };
  } catch {
    return { host: url, path: "" };
  }
};
const checkUrl = (v: string) => {
  try {
    const u = new URL(v.trim());
    if (
      u.protocol === "https:" ||
      (u.protocol === "http:" && /^(localhost|127\.0\.0\.1)$/.test(u.hostname))
    )
      return null;
    return "Endpoints need https:// (http:// works for localhost).";
  } catch {
    return v.trim()
      ? "That isn't a full URL. Start it with https://."
      : "Enter the URL that should receive events.";
  }
};

function Fold({
  open,
  reduced,
  children,
}: {
  open: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [kept, setKept] = React.useState(children);
  if (open && kept !== children) {
    setKept(children);
  }
  return (
    <div
      className="grid"
      inert={!open}
      aria-hidden={!open || undefined}
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 460ms ${EASE}, opacity ${open ? 320 : 180}ms ${EASE}`,
      }}
    >
      <div className="min-h-0 min-w-0 overflow-clip [overflow-clip-margin:6px]">
        {open ? children : kept}
      </div>
    </div>
  );
}

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3.5"
    >
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="1.9"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 100ms`
              : "none",
        }}
      />
    </svg>
  );
}

function EventChip({
  value,
  on,
  reduced,
  onToggle,
}: {
  value: string;
  on: boolean;
  reduced: boolean;
  onToggle: () => void;
}) {
  return (
    <button
      type="button"
      aria-pressed={on}
      onClick={onToggle}
      className={`inline-flex h-7 cursor-pointer items-center rounded-full px-2.5 font-mono text-[11.5px] transition-[background-color,color,box-shadow] duration-200 ${FOCUS} ${
        on
          ? "bg-accent text-foreground shadow-[inset_0_0_0_1px_var(--border)]"
          : "text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:text-foreground"
      }`}
    >
      <span
        className="grid"
        style={{
          gridTemplateColumns: on ? "1fr" : "0fr",
          transition: reduced ? "none" : `grid-template-columns 320ms ${EASE}`,
        }}
      >
        <span className="min-w-0 overflow-clip">
          <span className="mr-1 block">
            <Check drawn={on} reduced={reduced} />
          </span>
        </span>
      </span>
      {value}
    </button>
  );
}

/** The signing secret: dots until it's revealed, then the value and a copy button. */
function Secret({
  value,
  onReveal,
  onHide,
  reduced,
}: {
  value: string | null;
  onReveal?: () => Promise<void>;
  onHide: () => void;
  reduced: boolean;
}) {
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const [copied, setCopied] = React.useState(false);
  const ref = React.useRef<HTMLElement>(null);
  React.useLayoutEffect(() => {
    if (value && !reduced)
      ref.current?.animate(
        [
          { opacity: 0, filter: "blur(4px)" },
          { opacity: 1, filter: "blur(0px)" },
        ],
        { duration: 360, easing: EASE },
      );
  }, [value, reduced]);
  React.useEffect(() => {
    if (!copied) return;
    const timer = window.setTimeout(() => setCopied(false), 1400);
    return () => window.clearTimeout(timer);
  }, [copied]);
  return (
    <div className="flex min-w-0 items-center gap-1.5">
      <code
        ref={ref}
        className="min-w-0 flex-1 truncate rounded-[8px] bg-muted px-2 py-1 font-mono text-[11.5px] text-foreground shadow-[inset_0_0_0_1px_var(--border)]"
      >
        {value ?? "whsec_••••••••••••••••"}
      </code>
      {value ? (
        <>
          <button
            type="button"
            aria-label={copied ? "Secret copied" : "Copy secret"}
            onClick={async () => {
              try {
                await navigator.clipboard.writeText(value);
                setCopied(true);
              } catch {
                /* Selectable on screen. */
              }
            }}
            className={`relative grid size-7 shrink-0 cursor-pointer place-items-center rounded-full transition-colors hover:bg-accent ${FOCUS} ${copied ? "text-emerald-600 dark:text-emerald-400" : "text-muted-foreground hover:text-foreground"}`}
          >
            {[false, true].map((on) => (
              <span
                key={String(on)}
                aria-hidden="true"
                className="absolute inset-0 grid place-items-center"
                style={{
                  opacity: copied === on ? 1 : 0,
                  transform: copied === on ? "none" : "scale(0.6)",
                  transition: reduced
                    ? "none"
                    : `opacity 220ms ${EASE}, transform 340ms ${EASE}`,
                }}
              >
                {on ? (
                  <Check drawn={copied} reduced={reduced} />
                ) : (
                  <Copy className="size-3.5" strokeWidth={1.75} />
                )}
              </span>
            ))}
          </button>
          <button
            type="button"
            onClick={onHide}
            className={`h-7 shrink-0 cursor-pointer rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
          >
            Hide
          </button>
        </>
      ) : onReveal ? (
        <StatusButton
          size="sm"
          variant="ghost"
          status={status}
          labels={{
            idle: "Reveal",
            pending: "Revealing",
            success: "Reveal",
            error: "Try again",
          }}
          onClick={async () => {
            setStatus("pending");
            try {
              await onReveal();
              setStatus("idle");
            } catch {
              setStatus("error");
            }
          }}
        />
      ) : null}
    </div>
  );
}

function Switch({
  on,
  label,
  onToggle,
  reduced,
  busy,
}: {
  on: boolean;
  label: string;
  onToggle: () => void;
  reduced: boolean;
  busy: boolean;
}) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={on}
      aria-busy={busy || undefined}
      onClick={onToggle}
      className={`inline-flex h-7 cursor-pointer items-center gap-2 rounded-full pr-2.5 pl-1 text-[12px] font-medium transition-colors hover:bg-accent aria-busy:cursor-default ${FOCUS}`}
    >
      <span
        className={`relative h-5 w-9 shrink-0 rounded-full transition-[background-color,box-shadow] duration-300 ${on ? "bg-primary" : "bg-muted shadow-[inset_0_0_0_1px_var(--border)]"}`}
      >
        <span
          className="absolute top-0.5 left-0.5 size-4 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
          style={{
            transform: on ? "translateX(16px)" : "none",
            transition: reduced ? "none" : `transform 420ms ${THROW}`,
          }}
        />
      </span>
      <TextMorph>{busy ? "Saving" : label}</TextMorph>
    </button>
  );
}

interface EndpointProps {
  ep: WebhookEndpoint;
  open: boolean;
  log?: Log;
  secret: string | null;
  fresh: boolean;
  gone: boolean;
  toggling: boolean;
  reduced: boolean;
  appName: string;
  canReveal: boolean;
  canToggle: boolean;
  canDelete: boolean;
  canRedeliver: boolean;
  act: React.RefObject<Actions>;
}

type Actions = {
  open: (id: string) => void;
  test: (ep: WebhookEndpoint, event: string) => Promise<WebhookDelivery>;
  delivered: (ep: WebhookEndpoint, d: WebhookDelivery) => void;
  more: (ep: WebhookEndpoint) => void;
  redeliver: (ep: WebhookEndpoint, d: WebhookDelivery) => Promise<unknown>;
  reveal: (ep: WebhookEndpoint) => Promise<void>;
  hide: (ep: WebhookEndpoint) => void;
  toggle: (ep: WebhookEndpoint) => void;
  remove: (ep: WebhookEndpoint) => Promise<void>;
};

const Endpoint = React.memo(function Endpoint({
  ep,
  open,
  log,
  secret,
  fresh,
  gone,
  toggling,
  reduced,
  appName,
  canReveal,
  canToggle,
  canDelete,
  canRedeliver,
  act,
}: EndpointProps) {
  const ref = React.useRef<HTMLLIElement>(null);
  const { host, path } = split(ep.url);
  const enabled = ep.enabled !== false;
  const last = ep.lastDelivery;
  const failing =
    enabled && last && (last.status === null || last.status >= 500);

  React.useLayoutEffect(() => {
    if (fresh && !reduced)
      ref.current?.animate(
        [
          { opacity: 0, filter: "blur(4px)", transform: "translateY(-6px)" },
          { opacity: 1, filter: "blur(0px)", transform: "none" },
        ],
        { duration: 460, easing: EASE },
      );
  }, []);

  return (
    <li ref={ref} className="border-t border-border first:border-t-0">
      <Fold open={!gone} reduced={reduced}>
        <button
          type="button"
          aria-expanded={open}
          onClick={() => act.current.open(ep.id)}
          className={`flex w-full cursor-pointer items-center gap-3 px-4 py-3 text-left transition-colors hover:bg-accent/40 @md:px-5 ${FOCUS} focus-visible:ring-inset`}
        >
          <span
            aria-hidden="true"
            className={`size-1.5 shrink-0 rounded-full transition-colors duration-500 ${!enabled ? "bg-muted-foreground/40" : failing ? "bg-red-500" : "bg-emerald-500"}`}
          />
          <span className="min-w-0 flex-1">
            <span className="block truncate font-mono text-[12.5px]">
              <span className="text-foreground">{host}</span>
              <span className="text-muted-foreground">{path}</span>
            </span>
            <span className="mt-0.5 flex flex-wrap items-center gap-x-1.5 text-[11.5px] text-muted-foreground">
              <span className="inline-flex items-baseline tabular-nums">
                <NumberRoll value={ep.events.length} />
                &nbsp;
                <TextMorph>
                  {ep.events.length === 1 ? "event" : "events"}
                </TextMorph>
              </span>
              <span aria-hidden="true">·</span>
              {!enabled ? (
                <span>Disabled</span>
              ) : last ? (
                <span className="inline-flex items-center gap-1.5">
                  <StatusChip status={last.status} />
                  <RelativeTime date={last.at} />
                </span>
              ) : (
                <span>No deliveries yet</span>
              )}
            </span>
          </span>
          <svg
            viewBox="0 0 16 16"
            fill="none"
            aria-hidden="true"
            className="size-3.5 shrink-0 text-muted-foreground"
            style={{
              transform: open ? "rotate(180deg)" : "none",
              transition: reduced ? "none" : `transform 340ms ${EASE}`,
            }}
          >
            <path
              d="M4.5 6.25 8 9.75l3.5-3.5"
              stroke="currentColor"
              strokeWidth="1.6"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>

        <Fold open={open} reduced={reduced}>
          <div className="space-y-5 px-4 pt-1 pb-4 @md:px-5 @md:pb-5">
            <section aria-label="Send a test event">
              <p className="mb-2 text-[11.5px] font-medium text-muted-foreground">
                Send a test
              </p>
              <WebhookWire
                host={host}
                events={ep.events}
                from={appName}
                reduced={reduced}
                autoFocus={fresh && open}
                onSend={(event) => act.current.test(ep, event)}
                onDelivered={(d) => act.current.delivered(ep, d)}
              />
            </section>

            <section aria-label="Recent deliveries">
              <p className="mb-1 text-[11.5px] font-medium text-muted-foreground">
                Recent deliveries
              </p>
              <div className="rounded-[14px] px-1 shadow-[inset_0_0_0_1px_var(--border)]">
                <DeliveryList
                  deliveries={log?.items ?? []}
                  loading={Boolean(log?.loading) || !log}
                  more={Boolean(log?.more)}
                  onMore={() => act.current.more(ep)}
                  onRedeliver={
                    canRedeliver
                      ? (d) => act.current.redeliver(ep, d)
                      : undefined
                  }
                  reduced={reduced}
                />
              </div>
            </section>

            <div className="grid gap-4 @lg:grid-cols-2">
              <section aria-label="Signing secret" className="min-w-0">
                <p className="mb-1.5 text-[11.5px] font-medium text-muted-foreground">
                  Signing secret
                </p>
                <Secret
                  value={secret}
                  onReveal={
                    canReveal ? () => act.current.reveal(ep) : undefined
                  }
                  onHide={() => act.current.hide(ep)}
                  reduced={reduced}
                />
              </section>
              <section aria-label="Events" className="min-w-0">
                <p className="mb-1.5 text-[11.5px] font-medium text-muted-foreground">
                  Events
                </p>
                <p className="flex flex-wrap gap-1">
                  {ep.events.map((e) => (
                    <span
                      key={e}
                      className="rounded-full px-2 py-0.5 font-mono text-[11px] text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
                    >
                      {e}
                    </span>
                  ))}
                </p>
              </section>
            </div>

            {(canToggle || canDelete) && (
              <div className="flex items-center justify-between gap-3 border-t border-border pt-3">
                {canToggle ? (
                  <Switch
                    on={enabled}
                    label={enabled ? "Enabled" : "Disabled"}
                    busy={toggling}
                    reduced={reduced}
                    onToggle={() => !toggling && act.current.toggle(ep)}
                  />
                ) : (
                  <span />
                )}
                {canDelete && (
                  <ConfirmAction
                    icon={<Trash2 strokeWidth={1.75} />}
                    label={`Delete endpoint ${host}`}
                    labels={{
                      idle: "Delete endpoint",
                      pending: "Deleting",
                      success: "Deleted",
                      error: "Try again",
                    }}
                    onConfirm={() => act.current.remove(ep)}
                  />
                )}
              </div>
            )}
          </div>
        </Fold>
      </Fold>
    </li>
  );
});

export function Webhooks({
  value,
  defaultValue = NONE,
  onValueChange,
  events,
  onCreate,
  onTest,
  loadDeliveries,
  onRedeliver,
  onRevealSecret,
  onToggle,
  onDelete,
  appName = "Your app",
  title = "Webhooks",
  description = "Send events to your own server as they happen.",
  className = "",
  ...props
}: WebhooksProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [inner, setInner] = React.useState(defaultValue);
  const endpoints = value ?? inner;
  const [draft, setDraft] = React.useState<Draft | null>(null);
  const [openId, setOpenId] = React.useState<string | null>(null);
  const [logs, setLogs] = React.useState<Record<string, Log>>({});
  const [secrets, setSecrets] = React.useState<Record<string, string>>({});
  const [toggling, setToggling] = React.useState<Record<string, boolean>>({});
  const [gone, setGone] = React.useState<string[]>([]);
  const [fresh, setFresh] = React.useState<string | null>(null);
  const [announce, setAnnounce] = React.useState("");
  const urlRef = React.useRef<HTMLInputElement>(null);
  const addRef = React.useRef<HTMLButtonElement>(null);
  const formRef = React.useRef<HTMLFormElement>(null);
  const latest = React.useRef(endpoints);
  latest.current = endpoints;

  const commit = (next: WebhookEndpoint[]) => {
    if (value === undefined) setInner(next);
    onValueChange?.(next);
  };
  const patch = (epId: string, p: Partial<WebhookEndpoint>) =>
    commit(latest.current.map((e) => (e.id === epId ? { ...e, ...p } : e)));
  const setLog = (epId: string, f: (l: Log) => Log) =>
    setLogs((all) => ({
      ...all,
      [epId]: f(
        all[epId] ?? { items: [], loading: false, more: false, loaded: false },
      ),
    }));

  const load = async (ep: WebhookEndpoint, before?: WebhookDelivery) => {
    if (!loadDeliveries) return setLog(ep.id, (l) => ({ ...l, loaded: true }));
    setLog(ep.id, (l) => ({ ...l, loading: true }));
    try {
      const page = await loadDeliveries(ep, before);
      setLog(ep.id, (l) => ({
        items: before ? [...l.items, ...page] : page,
        loading: false,
        loaded: true,
        more: page.length > 0,
      }));
    } catch {
      setLog(ep.id, (l) => ({ ...l, loading: false, loaded: true }));
    }
  };

  const act = React.useRef<Actions>(null!);
  act.current = {
    open: (epId) => {
      setFresh(null);
      setOpenId((o) => (o === epId ? null : epId));
      const ep = latest.current.find((e) => e.id === epId);
      if (ep && openId !== epId && !logs[epId]?.loaded && !logs[epId]?.loading)
        load(ep);
    },
    test: (ep, event) => onTest(ep, event),
    delivered: (ep, d) => {
      setLog(ep.id, (l) => ({
        ...l,
        loaded: true,
        items: [d, ...l.items.filter((x) => x.id !== d.id)],
      }));
      patch(ep.id, { lastDelivery: { status: d.status, at: d.at } });
    },
    more: (ep) => {
      const items = logs[ep.id]?.items ?? [];
      load(ep, items[items.length - 1]);
    },
    redeliver: async (ep, d) => {
      if (!onRedeliver) return;
      const next = await onRedeliver(d, ep);
      act.current.delivered(ep, next);
      setAnnounce(`Redelivered ${d.event}: ${next.status ?? "no answer"}.`);
    },
    reveal: async (ep) => {
      if (!onRevealSecret) return;
      const s = await onRevealSecret(ep);
      setSecrets((all) => ({ ...all, [ep.id]: s }));
    },
    hide: (ep) =>
      setSecrets((all) =>
        Object.fromEntries(Object.entries(all).filter(([k]) => k !== ep.id)),
      ),
    toggle: async (ep) => {
      const next = ep.enabled === false;
      patch(ep.id, { enabled: next });
      setToggling((t) => ({ ...t, [ep.id]: true }));
      try {
        await onToggle?.(ep, next);
        setAnnounce(`${split(ep.url).host} ${next ? "enabled" : "disabled"}.`);
      } catch (e) {
        patch(ep.id, { enabled: !next });
        setAnnounce(message(e, "That change couldn't be saved."));
      } finally {
        setToggling((t) =>
          Object.fromEntries(Object.entries(t).filter(([k]) => k !== ep.id)),
        );
      }
    },
    remove: async (ep) => {
      await onDelete?.(ep);
      setAnnounce(`${split(ep.url).host} deleted.`);
      window.setTimeout(() => setGone((g) => [...g, ep.id]), 500);
      window.setTimeout(() => {
        commit(latest.current.filter((e) => e.id !== ep.id));
        setGone((g) => g.filter((x) => x !== ep.id));
        setOpenId((o) => (o === ep.id ? null : o));
      }, 1000);
    },
  };

  const openDraft = () => {
    if (draft) return;
    setDraft({
      url: "",
      events: events.slice(0, 1).map((e) => e.value),
      status: "idle",
      error: null,
    });
    requestAnimationFrame(() => urlRef.current?.focus({ preventScroll: true }));
  };
  const closeDraft = () => {
    setDraft(null);
    requestAnimationFrame(() => addRef.current?.focus({ preventScroll: true }));
  };

  const submit = async () => {
    if (!draft || draft.status === "pending") return;
    const why =
      checkUrl(draft.url) ??
      (draft.events.length ? null : "Pick at least one event.");
    if (why) {
      setDraft({ ...draft, error: why, status: "idle" });
      if (!reduced)
        formRef.current
          ?.querySelector("[data-url]")
          ?.animate(SHAKE, { duration: 380, easing: "ease-out" });
      return;
    }
    setDraft({ ...draft, status: "pending", error: null });
    try {
      const ep = await onCreate({
        url: draft.url.trim(),
        events: draft.events,
      });
      commit([ep, ...latest.current]);
      setLogs((all) => ({
        ...all,
        [ep.id]: { items: [], loading: false, more: false, loaded: true },
      }));
      setFresh(ep.id);
      setOpenId(ep.id);
      setDraft(null);
      setAnnounce(`${split(ep.url).host} added. Send a test to check it.`);
    } catch (e) {
      setDraft(
        (d) =>
          d && {
            ...d,
            status: "error",
            error: message(e, "The endpoint couldn't be added."),
          },
      );
    }
  };

  const busyDraft = draft?.status === "pending";
  return (
    <div
      className={`@container w-full rounded-[22px] border border-border bg-background text-foreground ${className}`}
      {...props}
    >
      <div className="flex items-start justify-between gap-3 px-4 pt-4 pb-3.5 @md:px-5 @md:pt-5">
        <div className="min-w-0">
          <p className="flex items-baseline gap-2 text-[14px] font-medium tracking-[-0.01em]">
            {title}
            <span className="text-[12px] font-normal text-muted-foreground tabular-nums">
              <NumberRoll value={endpoints.length} />
            </span>
          </p>
          <p className="mt-0.5 text-[12px] text-muted-foreground">
            {description}
          </p>
        </div>
        <button
          ref={addRef}
          type="button"
          onClick={openDraft}
          aria-disabled={Boolean(draft) || undefined}
          aria-expanded={Boolean(draft)}
          aria-controls={`${id}-form`}
          className={`inline-flex h-7 shrink-0 cursor-pointer items-center gap-1.5 rounded-full px-3 text-[12px] font-medium shadow-[inset_0_0_0_1px_var(--border)] transition-[background-color,opacity] hover:bg-accent aria-disabled:cursor-default aria-disabled:opacity-40 aria-disabled:hover:bg-transparent ${FOCUS}`}
        >
          <Plus className="size-3.5" strokeWidth={1.75} aria-hidden="true" />
          Add endpoint
        </button>
      </div>

      <Fold open={Boolean(draft)} reduced={reduced}>
        <form
          ref={formRef}
          id={`${id}-form`}
          noValidate
          className="border-t border-border px-4 py-3.5 @md:px-5"
          onSubmit={(e) => {
            e.preventDefault();
            submit();
          }}
          onKeyDown={(e) => {
            if (e.key === "Escape" && !busyDraft) {
              e.preventDefault();
              closeDraft();
            }
          }}
        >
          <label
            htmlFor={`${id}-url`}
            className="text-[11.5px] text-muted-foreground"
          >
            Endpoint URL
          </label>
          <input
            ref={urlRef}
            data-url=""
            id={`${id}-url`}
            type="url"
            inputMode="url"
            value={draft?.url ?? ""}
            readOnly={busyDraft}
            onChange={(e) =>
              setDraft(
                (d) =>
                  d && {
                    ...d,
                    url: e.target.value,
                    error: null,
                    status: "idle",
                  },
              )
            }
            placeholder="https://api.yourcompany.com/webhooks"
            autoComplete="off"
            spellCheck={false}
            aria-invalid={Boolean(draft?.error) || undefined}
            aria-describedby={`${id}-line`}
            className={`mt-1 h-9 w-full rounded-[10px] bg-transparent px-3 font-mono text-[16px] text-foreground outline-none transition-shadow placeholder:font-sans placeholder:text-muted-foreground/70 [@media(pointer:fine)]:text-[12.5px] ${
              draft?.error
                ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_45%,transparent)]"
                : "shadow-[inset_0_0_0_1px_var(--border)] focus:shadow-[inset_0_0_0_1px_var(--ring)]"
            }`}
          />
          <p className="mt-3 text-[11.5px] text-muted-foreground">Events</p>
          <div
            role="group"
            aria-label="Events to send"
            className="mt-1.5 flex flex-wrap gap-1.5"
          >
            {events.map((ev) => {
              const on = Boolean(draft?.events.includes(ev.value));
              return (
                <EventChip
                  key={ev.value}
                  value={ev.value}
                  on={on}
                  reduced={reduced}
                  onToggle={() =>
                    setDraft(
                      (d) =>
                        d && {
                          ...d,
                          error: null,
                          events: on
                            ? d.events.filter((x) => x !== ev.value)
                            : [...d.events, ev.value],
                        },
                    )
                  }
                />
              );
            })}
          </div>
          <div className="mt-3.5 flex flex-wrap items-center justify-end gap-x-3 gap-y-2">
            <p
              id={`${id}-line`}
              className={`mr-auto min-w-0 text-[11.5px] ${draft?.error ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
            >
              {draft?.error ??
                "We sign every request so your server can check it came from us."}
            </p>
            <div className="flex items-center gap-1">
              <button
                type="button"
                onClick={closeDraft}
                disabled={busyDraft}
                className={`h-7 cursor-pointer rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:cursor-default disabled:opacity-50 ${FOCUS}`}
              >
                Cancel
              </button>
              <StatusButton
                type="submit"
                size="sm"
                status={draft?.status ?? "idle"}
                labels={{
                  idle: "Add endpoint",
                  pending: "Adding",
                  error: "Try again",
                }}
              />
            </div>
          </div>
        </form>
      </Fold>

      <div className="border-t border-border">
        <ul aria-label={title}>
          {endpoints.map((ep) => (
            <Endpoint
              key={ep.id}
              ep={ep}
              open={openId === ep.id}
              log={logs[ep.id]}
              secret={secrets[ep.id] ?? null}
              fresh={fresh === ep.id}
              gone={gone.includes(ep.id)}
              toggling={Boolean(toggling[ep.id])}
              reduced={reduced}
              appName={appName}
              canReveal={Boolean(onRevealSecret)}
              canToggle={Boolean(onToggle)}
              canDelete={Boolean(onDelete)}
              canRedeliver={Boolean(onRedeliver)}
              act={act}
            />
          ))}
        </ul>
        <Fold open={!endpoints.length && !draft} reduced={reduced}>
          <p className="px-4 py-6 text-center text-[12.5px] text-muted-foreground @md:px-5">
            No endpoints yet. Add one to start receiving events.
          </p>
        </Fold>
      </div>

      <span className="sr-only" role="status">
        {announce}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import { StatusButton, type ActionStatus } from "./status-button";

/* ─────────────────────────────────────────────────────────
 * CONFIRM ACTION: an icon that asks before it acts
 *
 *   ask       a click and the icon's own circle stretches into
 *             a pill: the confirm button opens out to its left
 *             and the icon turns into a cross that takes it back
 *   act       the confirm button is a status button, so it says
 *             Revoking, Revoked or Try again in place
 *   leave     Escape, the cross, or a click or focus anywhere
 *             else folds it back into the icon
 *
 * Nothing opens over the row it belongs to; the question sits
 * where the icon was.
 * ───────────────────────────────────────────────────────── */

export interface ConfirmActionProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onClick"
> {
  icon: React.ReactNode;
  /** The icon button's accessible name, e.g. "Revoke Production key". */
  label: string;
  /** The confirm button's words per state, e.g. { idle: "Revoke", pending: "Revoking", success: "Revoked" }. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** "danger" makes the confirm red. */
  tone?: "danger" | "default";
  /** Runs once on confirm. Throw (or reject) to show Try again. */
  onConfirm: () => Promise<unknown> | unknown;
  /** Back to the icon this long after success (ms); 0 keeps "done" until the row goes. */
  resetAfter?: number;
  disabled?: boolean;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Cross() {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3.5"
    >
      <path
        d="M4.5 4.5l7 7M11.5 4.5l-7 7"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function ConfirmAction({
  icon,
  label,
  labels,
  tone = "danger",
  onConfirm,
  resetAfter = 0,
  disabled = false,
  className = "",
  ...props
}: ConfirmActionProps) {
  const reduced = useReducedMotion();
  const [asking, setAsking] = React.useState(false);
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const iconRef = React.useRef<HTMLButtonElement>(null);
  const run = React.useRef(0);
  const busy = status === "pending" || status === "success";

  const cancel = React.useCallback(
    (refocus: boolean) => {
      if (status === "pending") return;
      run.current++;
      setAsking(false);
      setStatus("idle");
      if (refocus) iconRef.current?.focus({ preventScroll: true });
    },
    [status],
  );

  // The question is open: its button takes focus once it's there to take it.
  React.useEffect(() => {
    if (asking && status === "idle")
      wrapRef.current
        ?.querySelector<HTMLButtonElement>("[data-confirm]")
        ?.focus({ preventScroll: true });
  }, [asking, status]);

  React.useEffect(() => {
    if (!asking) return;
    const onDown = (e: PointerEvent) => {
      if (!wrapRef.current?.contains(e.target as Node)) cancel(false);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [asking, cancel]);

  const confirm = async () => {
    if (busy) return;
    const mine = ++run.current;
    setStatus("pending");
    try {
      await onConfirm();
      if (run.current === mine) setStatus("success");
    } catch {
      if (run.current === mine) setStatus("error");
    }
  };

  const t = `${reduced ? 0 : 420}ms ${EASE}`;
  const red =
    tone === "danger"
      ? "text-red-600! hover:bg-red-500/10! dark:text-red-400!"
      : "";

  return (
    <div
      ref={wrapRef}
      className={`relative inline-flex h-7 shrink-0 items-center rounded-full ${className}`}
      onKeyDown={(e) => {
        if (e.key === "Escape" && asking) {
          e.preventDefault();
          e.stopPropagation();
          cancel(true);
        }
      }}
      onBlur={(e) => {
        if (
          asking &&
          !busy &&
          document.hasFocus() &&
          !wrapRef.current?.contains(e.relatedTarget as Node)
        )
          cancel(false);
      }}
      {...props}
    >
      {/* The icon's circle, stretched into the pill round the question. */}
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 rounded-full"
        style={{
          boxShadow: `inset 0 0 0 1px ${asking ? "var(--border)" : "transparent"}`,
          transition: `box-shadow ${t}`,
        }}
      />
      <span
        className="grid"
        inert={!asking}
        style={{
          gridTemplateColumns: asking ? "1fr" : "0fr",
          opacity: asking ? 1 : 0,
          filter: asking || reduced ? "none" : "blur(3px)",
          transition: `grid-template-columns ${t}, opacity ${reduced ? 0 : asking ? 320 : 160}ms ${EASE}, filter ${t}`,
        }}
      >
        <span className="min-w-0 overflow-hidden [clip-path:inset(-2px_0_-2px_0)]">
          <span className="flex w-max items-center pl-0.5">
            <StatusButton
              data-confirm=""
              size="sm"
              variant="ghost"
              status={status}
              labels={{
                idle: "Confirm",
                pending: "Working",
                success: "Done",
                error: "Try again",
                ...labels,
              }}
              onClick={confirm}
              onReset={resetAfter ? () => cancel(false) : undefined}
              resetAfter={resetAfter || undefined}
              className={`h-[26px]! ${status === "error" ? "" : red}`}
            />
          </span>
        </span>
      </span>
      <button
        ref={iconRef}
        type="button"
        aria-label={asking ? "Cancel" : label}
        aria-expanded={asking}
        disabled={disabled}
        onClick={() => (asking ? cancel(true) : setAsking(true))}
        className={`relative grid size-7 shrink-0 cursor-pointer place-items-center rounded-full text-muted-foreground transition-colors duration-150 hover:bg-accent hover:text-foreground disabled:cursor-default disabled:opacity-40 aria-disabled:cursor-default ${FOCUS}`}
        aria-disabled={busy || undefined}
      >
        {[icon, <Cross key="x" />].map((glyph, i) => {
          const on = (i === 1) === asking;
          return (
            <span
              key={i}
              aria-hidden="true"
              className="absolute inset-0 grid place-items-center [&_svg]:size-3.5"
              style={{
                opacity: on ? 1 : 0,
                transform: on ? "none" : "scale(0.6)",
                filter: on || reduced ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {glyph}
            </span>
          );
        })}
      </button>
    </div>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * RELATIVE TIME: "2 min ago" that keeps itself true
 *
 *   tick      it re-renders only when the words would change:
 *             on the next minute under an hour, the next hour
 *             under a day; nothing runs between
 *   roll      the number rolls up ("2 min" → "3 min") and the
 *             unit morphs when it changes ("59 min" → "1 h")
 *   date      past a week it settles on the date ("12 Sep")
 *
 * Until it's mounted it renders the date, so the server and the
 * first paint agree; the hover title is always the full time.
 * ───────────────────────────────────────────────────────── */

export type DateLike = Date | string | number;

export interface RelativeTimeProps extends Omit<
  React.HTMLAttributes<HTMLElement>,
  "children"
> {
  date: DateLike;
  /** Said before the time, e.g. "Last used". */
  prefix?: string;
  /** Under a minute. */
  justNow?: string;
  locales?: string | string[];
}

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

export const toTime = (d: DateLike) =>
  d instanceof Date
    ? d.getTime()
    : typeof d === "number"
      ? d
      : new Date(d).getTime();

const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

/** "12 Sep", with the year when it isn't this one; pass locales to use the browser's own format. */
export function formatDate(d: DateLike, locales?: string | string[]) {
  const t = new Date(toTime(d));
  const sameYear = t.getFullYear() === new Date().getFullYear();
  if (locales)
    return t.toLocaleDateString(
      locales,
      sameYear
        ? { day: "numeric", month: "short" }
        : { day: "numeric", month: "short", year: "numeric" },
    );
  return `${t.getDate()} ${MONTHS[t.getMonth()]}${sameYear ? "" : ` ${t.getFullYear()}`}`;
}

type Parts = { n: number | null; unit: string; next: number };

function parts(
  at: number,
  now: number,
  justNow: string,
  locales?: string | string[],
): Parts {
  const ago = Math.max(0, now - at);
  if (ago < MINUTE) return { n: null, unit: justNow, next: MINUTE - ago };
  if (ago < HOUR)
    return {
      n: Math.floor(ago / MINUTE),
      unit: "min ago",
      next: MINUTE - (ago % MINUTE),
    };
  if (ago < DAY) {
    const h = Math.floor(ago / HOUR);
    return {
      n: h,
      unit: h === 1 ? "hour ago" : "hours ago",
      next: HOUR - (ago % HOUR),
    };
  }
  if (ago < 7 * DAY) {
    const d = Math.floor(ago / DAY);
    return {
      n: d,
      unit: d === 1 ? "day ago" : "days ago",
      next: DAY - (ago % DAY),
    };
  }
  return { n: null, unit: formatDate(at, locales), next: 0 };
}

const subscribeMounted = () => () => {};

export function RelativeTime({
  date,
  prefix,
  justNow = "just now",
  locales,
  className = "",
  ...props
}: RelativeTimeProps) {
  const at = toTime(date);
  const mounted = React.useSyncExternalStore(
    subscribeMounted,
    () => true,
    () => false,
  );
  const [now, setNow] = React.useState(() => Date.now());
  const p = parts(at, mounted ? now : at + 8 * DAY, justNow, locales);

  // One timer, set for the moment the words change.
  React.useEffect(() => {
    if (!mounted || !p.next) return;
    const timer = window.setTimeout(() => setNow(Date.now()), p.next + 50);
    return () => window.clearTimeout(timer);
  }, [mounted, p.next, now]);

  React.useEffect(() => {
    const timer = window.setTimeout(() => setNow(Date.now()), 0);
    return () => window.clearTimeout(timer);
  }, [at]);

  const iso = new Date(at).toISOString();
  return (
    <time
      dateTime={iso}
      title={new Date(at).toLocaleString(locales ?? "en-GB", {
        dateStyle: "medium",
        timeStyle: "short",
      })}
      className={`inline-flex items-baseline whitespace-nowrap tabular-nums ${className}`}
      {...props}
    >
      {prefix && <span>{prefix}&nbsp;</span>}
      {/* Remounted once on the client, so the first real words appear without a morph. */}
      <Words key={mounted ? "client" : "server"} n={p.n} unit={p.unit} />
    </time>
  );
}

function Words({ n, unit }: { n: number | null; unit: string }) {
  return (
    <>
      <span
        aria-hidden={n === null || undefined}
        className="inline-grid transition-[grid-template-columns] duration-[380ms] ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none"
        style={{ gridTemplateColumns: n === null ? "0fr" : "1fr" }}
      >
        <span className="min-w-0 [clip-path:inset(-4px_0)]">
          <span className="inline-flex items-baseline pr-[0.25em]">
            <NumberRoll value={n ?? 1} direction="up" />
          </span>
        </span>
      </span>
      <TextMorph>{unit}</TextMorph>
    </>
  );
}

"use client";

import * as React from "react";
import { RelativeTime, type DateLike } from "./relative-time";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import { useRowMotion } from "./use-row-motion";

/* ─────────────────────────────────────────────────────────
 * WEBHOOK DELIVERIES: what was sent, and what came back
 *
 *   rows      the status code in its colour, the event, when,
 *             and how long the endpoint took; new deliveries
 *             fade in on top while the rest glide down
 *   open      a row opens by height into Request and Response,
 *             the tab highlight sliding between them
 *   redeliver Redeliver → Sending → Sent; the new attempt
 *             arrives on top
 * ───────────────────────────────────────────────────────── */

export interface WebhookDelivery {
  id: string;
  event: string;
  /** The endpoint's HTTP status, or null when it never answered. */
  status: number | null;
  durationMs?: number;
  at: DateLike;
  attempt?: number;
  /** The body sent (JSON as text). */
  request?: string;
  /** What came back. */
  response?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const chip = (status: number | null) =>
  status === null || status >= 500
    ? "bg-red-500/10 text-red-700 dark:text-red-400"
    : status >= 300
      ? "bg-amber-500/10 text-amber-800 dark:text-amber-400"
      : "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400";

export function StatusChip({ status }: { status: number | null }) {
  return (
    <span
      className={`inline-flex h-5 w-[2.6rem] shrink-0 items-center justify-center rounded-[6px] font-mono text-[11px] font-medium tabular-nums ${chip(status)}`}
    >
      {status ?? "—"}
    </span>
  );
}

const pretty = (text?: string) => {
  if (!text) return "";
  try {
    return JSON.stringify(JSON.parse(text), null, 2);
  } catch {
    return text;
  }
};

function Bodies({ d, reduced }: { d: WebhookDelivery; reduced: boolean }) {
  const id = React.useId();
  const [tab, setTab] = React.useState<"request" | "response">("request");
  const refs = React.useRef<Record<string, HTMLButtonElement | null>>({});
  const [bar, setBar] = React.useState({ left: 0, width: 0, ready: false });
  React.useLayoutEffect(() => {
    const b = refs.current[tab];
    if (b)
      setBar((p) =>
        p.left === b.offsetLeft && p.width === b.offsetWidth
          ? p
          : { left: b.offsetLeft, width: b.offsetWidth, ready: p.width > 0 },
      );
  }, [tab]);
  const body = pretty(tab === "request" ? d.request : d.response);
  return (
    <div className="mt-1 mb-2 ml-2 rounded-[12px] shadow-[inset_0_0_0_1px_var(--border)] @md:ml-[3.35rem]">
      <div
        role="tablist"
        aria-label="Delivery body"
        className="relative flex gap-1 px-1.5 pt-1.5"
      >
        <span
          aria-hidden="true"
          className="absolute top-1.5 left-0 h-6 rounded-full bg-accent"
          style={{
            width: bar.width,
            transform: `translateX(${bar.left}px)`,
            transition:
              bar.ready && !reduced
                ? `transform 360ms ${EASE}, width 360ms ${EASE}`
                : "none",
          }}
        />
        {(["request", "response"] as const).map((t) => (
          <button
            key={t}
            ref={(el) => {
              refs.current[t] = el;
            }}
            role="tab"
            id={`${id}-${t}`}
            aria-selected={tab === t}
            aria-controls={`${id}-panel`}
            tabIndex={tab === t ? 0 : -1}
            onClick={() => setTab(t)}
            onKeyDown={(e) => {
              if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
              e.preventDefault();
              const next = t === "request" ? "response" : "request";
              setTab(next);
              refs.current[next]?.focus();
            }}
            className={`relative h-6 cursor-pointer rounded-full px-2.5 text-[11.5px] font-medium capitalize transition-colors ${FOCUS} ${tab === t ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}
          >
            {t}
          </button>
        ))}
      </div>
      <pre
        id={`${id}-panel`}
        role="tabpanel"
        aria-labelledby={`${id}-${tab}`}
        className="max-h-56 overflow-auto px-3 py-2 font-mono text-[11.5px] leading-[1.55] whitespace-pre-wrap break-all text-foreground"
      >
        {body || (
          <span className="text-muted-foreground">
            {tab === "request"
              ? "No body was kept."
              : "The endpoint sent no body."}
          </span>
        )}
      </pre>
    </div>
  );
}

function Redeliver({ onRedeliver }: { onRedeliver: () => Promise<unknown> }) {
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  return (
    <StatusButton
      size="sm"
      variant="ghost"
      status={status}
      labels={{
        idle: "Redeliver",
        pending: "Sending",
        success: "Sent",
        error: "Try again",
      }}
      onReset={() => setStatus("idle")}
      resetAfter={1600}
      onClick={async () => {
        setStatus("pending");
        try {
          await onRedeliver();
          setStatus("success");
        } catch {
          setStatus("error");
        }
      }}
    />
  );
}

const Row = React.memo(function Row({
  d,
  open,
  reduced,
  toggle,
  redeliver,
}: {
  d: WebhookDelivery;
  open: boolean;
  reduced: boolean;
  toggle: React.RefObject<(id: string) => void>;
  redeliver?: React.RefObject<(d: WebhookDelivery) => Promise<unknown>>;
}) {
  return (
    <li data-row-id={d.id} className="border-t border-border first:border-t-0">
      <div className="flex items-center gap-2 py-1.5 pr-1">
        <button
          type="button"
          aria-expanded={open}
          onClick={() => toggle.current(d.id)}
          className={`flex min-w-0 flex-1 cursor-pointer items-center gap-3 rounded-[8px] px-2 py-1 text-left transition-colors hover:bg-accent/70 ${FOCUS}`}
        >
          <StatusChip status={d.status} />
          <span className="min-w-0 flex-1">
            <span className="block truncate font-mono text-[12px] text-foreground">
              {d.event}
            </span>
            <span className="flex min-w-0 items-baseline gap-1.5 overflow-hidden text-[11.5px] whitespace-nowrap text-muted-foreground">
              <RelativeTime className="shrink-0" date={d.at} />
              {/* On a narrow card the time is enough; how long it took shows when there's room. */}
              {d.durationMs !== undefined && (
                <span className="hidden gap-1.5 @sm:inline-flex">
                  <span aria-hidden="true">·</span>
                  <span className="tabular-nums">
                    {Math.round(d.durationMs).toLocaleString("en-GB")} ms
                  </span>
                </span>
              )}
              {d.attempt && d.attempt > 1 ? (
                <>
                  <span aria-hidden="true">·</span>
                  <span className="truncate">attempt {d.attempt}</span>
                </>
              ) : null}
            </span>
          </span>
          <svg
            viewBox="0 0 16 16"
            fill="none"
            aria-hidden="true"
            className="size-3 shrink-0 text-muted-foreground"
            style={{
              transform: open ? "rotate(180deg)" : "none",
              transition: reduced ? "none" : `transform 320ms ${EASE}`,
            }}
          >
            <path
              d="M4.5 6.25 8 9.75l3.5-3.5"
              stroke="currentColor"
              strokeWidth="1.6"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
        {redeliver && <Redeliver onRedeliver={() => redeliver.current(d)} />}
      </div>
      <div
        className="grid"
        inert={!open}
        style={{
          gridTemplateRows: open ? "1fr" : "0fr",
          transition: reduced ? "none" : `grid-template-rows 380ms ${EASE}`,
        }}
      >
        <div className="min-h-0 min-w-0 overflow-clip">
          {open && <Bodies d={d} reduced={reduced} />}
        </div>
      </div>
    </li>
  );
});

export interface DeliveryListProps {
  deliveries: WebhookDelivery[];
  loading: boolean;
  /** More can be loaded. */
  more: boolean;
  onMore?: () => void;
  onRedeliver?: (d: WebhookDelivery) => Promise<unknown>;
  reduced: boolean;
}

export function DeliveryList({
  deliveries,
  loading,
  more,
  onMore,
  onRedeliver,
  reduced,
}: DeliveryListProps) {
  const [open, setOpen] = React.useState<string | null>(null);
  const listRef = React.useRef<HTMLUListElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);
  const ranks = React.useMemo(
    () => new Map(deliveries.map((d, i) => [d.id, i])),
    [deliveries],
  );
  useRowMotion(listRef, { reduced, ranks, ghosts: ghostRef });
  const toggle = React.useRef<(id: string) => void>(() => {});
  const redeliver = React.useRef<(d: WebhookDelivery) => Promise<unknown>>(
    async () => {},
  );
  React.useLayoutEffect(() => {
    toggle.current = (id) => setOpen((o) => (o === id ? null : id));
    redeliver.current = (d) => onRedeliver?.(d) ?? Promise.resolve();
  });

  return (
    <div>
      <div className="relative">
        <ul
          ref={listRef}
          aria-label="Recent deliveries"
          aria-busy={loading || undefined}
          className="relative"
        >
          {deliveries.map((d) => (
            <Row
              key={d.id}
              d={d}
              open={open === d.id}
              reduced={reduced}
              toggle={toggle}
              redeliver={onRedeliver ? redeliver : undefined}
            />
          ))}
        </ul>
        <div
          ref={ghostRef}
          aria-hidden="true"
          className="pointer-events-none absolute inset-0"
        />
      </div>
      {(loading || !deliveries.length || more) && (
        <div className="flex h-9 items-center justify-center gap-2 text-[12px] text-muted-foreground">
          {loading ? (
            <>
              <span className="size-3 animate-spin rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none" />
              Loading deliveries
            </>
          ) : !deliveries.length ? (
            "Nothing delivered yet. Send a test to see one here."
          ) : (
            <button
              type="button"
              onClick={onMore}
              className={`h-7 cursor-pointer rounded-full px-3 font-medium text-foreground transition-colors hover:bg-accent ${FOCUS}`}
            >
              <TextMorph>Show older</TextMorph>
            </button>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * ROW MOTION: rows that keep their place on screen
 *
 *   glide     after any render (a sort, a filter, new data from
 *             the server) every row that moved glides from its
 *             old place to its new one. Glides are additive, so
 *             a change that lands mid-glide adds its own offset
 *             instead of restarting anything
 *   travel    a row that sorts onto the page slides in from the
 *             side where it ranked before; one that sorts off
 *             slides out toward its new rank
 *   enter     a row that's new to the list fades in where it
 *             lands while the rows below glide clear of it
 *   leave     a row that's gone folds away where it stood. Its
 *             copy is the row's own element, detached by React
 *             and moved into a layer React never renders into,
 *             so a leaving row costs no render at all
 *   stagger   a sort can ask for the rows to set off one after
 *             another, top first
 *
 * Positions are layout offsets (transforms ignored), kept after
 * every render and whenever the list changes size (a row
 * opening its detail), so they're never stale. Rows are found
 * by data-row-id; ranks are their places in the whole sorted
 * list, not just the page.
 * ───────────────────────────────────────────────────────── */

type Seen = { top: number; height: number; el: HTMLElement };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const GLIDE = 480;

export function useRowMotion(
  container: React.RefObject<HTMLElement | null>,
  {
    reduced,
    resetKey,
    ranks,
    ghosts,
  }: {
    reduced: boolean;
    resetKey?: string | number;
    ranks: ReadonlyMap<string, number>;
    ghosts: React.RefObject<HTMLElement | null>;
  },
) {
  const seen = React.useRef(new Map<string, Seen>());
  const lastRanks = React.useRef(ranks);
  const lastKey = React.useRef(resetKey);
  const staggerNext = React.useRef(false);

  const read = React.useCallback(() => {
    const out = new Map<string, Seen>();
    container.current
      ?.querySelectorAll<HTMLElement>("[data-row-id]")
      .forEach((el) =>
        out.set(el.dataset.rowId!, {
          top: el.offsetTop,
          height: el.offsetHeight,
          el,
        }),
      );
    return out;
  }, [container]);

  /** The row React just removed, back on screen where it stood, leaving: sliding toward where it went, or folding. */
  const leave = (was: Seen, dy: number) => {
    const layer = ghosts.current;
    const el = was.el;
    if (!layer || el.isConnected) return;
    // No getAnimations() here (it flushes style for the whole page): the exit below is added last and replaces any
    // glide still on the element.
    el.removeAttribute("data-row-id");
    el.removeAttribute("tabindex");
    el.setAttribute("aria-hidden", "true");
    el.inert = true;
    Object.assign(el.style, {
      position: "absolute",
      left: "0",
      right: "0",
      top: `${was.top}px`,
      height: `${was.height}px`,
      margin: "0",
      overflow: "hidden",
    });
    layer.appendChild(el);
    const a = el.animate(
      dy
        ? [
            { transform: "translateY(0px)", opacity: 1, filter: "blur(0px)" },
            {
              transform: `translateY(${dy}px)`,
              opacity: 0,
              filter: "blur(3px)",
            },
          ]
        : [
            { opacity: 1, transform: "none", filter: "blur(0px)" },
            { opacity: 0, transform: "scale(0.985)", filter: "blur(4px)" },
          ],
      { duration: dy ? 360 : 280, easing: EASE, fill: "forwards" },
    );
    a.onfinish = a.oncancel = () => el.remove();
  };

  React.useLayoutEffect(() => {
    const el = container.current;
    if (!el) return;
    const before = seen.current;
    const after = read();
    const prevRanks = lastRanks.current;
    seen.current = after;
    lastRanks.current = ranks;
    const stagger = staggerNext.current;
    staggerNext.current = false;
    if (lastKey.current !== resetKey) {
      // A different page: the caller slides the whole body; nothing glides and nothing folds.
      lastKey.current = resetKey;
      return;
    }
    if (reduced || !before.size) return;

    // A typical row's height. Rows that come onto or leave the page only hint at the way they went (a row and a
    // quarter at most), so the list never shows holes while they travel.
    const heights = [...after.values()]
      .map((b) => b.height)
      .sort((a, b) => a - b);
    const rowH = heights[Math.floor(heights.length / 2)] ?? 48;
    const clamp = (dy: number) =>
      Math.max(-rowH * 1.25, Math.min(rowH * 1.25, dy));

    let order = 0;
    after.forEach((now, id) => {
      const row = now.el;
      const was = before.get(id);
      const delay = stagger ? Math.min(order++ * 16, 200) : 0;
      if (was) {
        const dy = was.top - now.top;
        if (Math.abs(dy) < 0.5) return;
        row.animate(
          [
            { transform: `translateY(${dy}px)`, zIndex: 1 },
            { transform: "translateY(0px)", zIndex: 1 },
          ],
          {
            duration: GLIDE,
            delay,
            easing: EASE,
            composite: "add",
            fill: "backwards",
          },
        );
        return;
      }
      const from = prevRanks.get(id);
      const to = ranks.get(id);
      if (from !== undefined && to !== undefined) {
        // It ranked somewhere off the page: it comes in from that side.
        row.animate(
          [
            {
              transform: `translateY(${clamp((from - to) * rowH)}px)`,
              opacity: 0,
              filter: "blur(3px)",
            },
            { transform: "translateY(0px)", opacity: 1, filter: "blur(0px)" },
          ],
          {
            duration: GLIDE,
            delay: delay / 2,
            easing: EASE,
            fill: "backwards",
          },
        );
        return;
      }
      row.animate(
        [
          { opacity: 0, filter: "blur(4px)" },
          { opacity: 1, filter: "blur(0px)" },
        ],
        { duration: 420, delay: 90, easing: EASE, fill: "backwards" },
      );
    });

    // Still in the list, just not on this page: its copy slides toward where it went. Gone for good: it folds.
    before.forEach((was, id) => {
      if (after.has(id)) return;
      const from = prevRanks.get(id);
      const to = ranks.get(id);
      leave(
        was,
        from !== undefined && to !== undefined
          ? clamp((to - from) * rowH) || rowH
          : 0,
      );
    });
  });

  // The list changed size without a render of ours (a detail opening by transition): keep the positions true.
  React.useEffect(() => {
    const el = container.current;
    if (!el) return;
    const observer = new ResizeObserver(() => {
      seen.current = read();
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [container, read]);

  return {
    /** The next change (a sort) sets the rows off one after another. */
    stagger: () => {
      staggerNext.current = true;
    },
  };
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { PillSelect } from "./imported-pill-select";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import type { WebhookDelivery } from "./webhook-deliveries";

/* ─────────────────────────────────────────────────────────
 * WEBHOOK WIRE: "Send test", drawn as the request it is
 *
 *   out       a bead leaves your app and runs the thin line to
 *             the endpoint
 *   waiting   the endpoint's chip pulses while it answers
 *   back      the bead comes home in the answer's colour, and
 *             the result rolls in: "200 OK in 182 ms"
 *   failed    a 5xx, or no answer, comes back red and the
 *             button shakes
 * ───────────────────────────────────────────────────────── */

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const TRAVEL = "cubic-bezier(0.65,0,0.35,1)";

const REASONS: Record<number, string> = {
  200: "OK",
  201: "Created",
  202: "Accepted",
  204: "No Content",
  301: "Moved",
  302: "Found",
  400: "Bad Request",
  401: "Unauthorized",
  403: "Forbidden",
  404: "Not Found",
  405: "Method Not Allowed",
  408: "Request Timeout",
  410: "Gone",
  413: "Too Large",
  422: "Unprocessable",
  429: "Too Many Requests",
  500: "Internal Server Error",
  502: "Bad Gateway",
  503: "Service Unavailable",
  504: "Gateway Timeout",
};
export const reasonFor = (status: number | null) =>
  status === null
    ? "No answer"
    : (REASONS[status] ??
      (status < 300 ? "OK" : status < 500 ? "Refused" : "Server error"));
export const toneFor = (status: number | null) =>
  status === null || status >= 500
    ? "red"
    : status >= 400
      ? "amber"
      : status >= 300
        ? "amber"
        : "emerald";
const COLOR = {
  emerald: "var(--color-emerald-500)",
  amber: "var(--color-amber-500)",
  red: "var(--color-red-500)",
};
const TEXT = {
  emerald: "text-emerald-600 dark:text-emerald-400",
  amber: "text-amber-700 dark:text-amber-400",
  red: "text-red-600 dark:text-red-400",
};

export interface WebhookWireProps {
  /** The endpoint's host, shown at the far end of the wire. */
  host: string;
  /** Events the test can send; the first is picked. */
  events: string[];
  onSend: (event: string) => Promise<WebhookDelivery>;
  /** Called with the delivery the test made, e.g. to add it to the list. */
  onDelivered?: (delivery: WebhookDelivery) => void;
  reduced: boolean;
  autoFocus?: boolean;
  /** Your app's name at the near end. */
  from?: string;
}

export function WebhookWire({
  host,
  events,
  onSend,
  onDelivered,
  reduced,
  autoFocus,
  from = "You",
}: WebhookWireProps) {
  const [event, setEvent] = React.useState(events[0] ?? "");
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const [result, setResult] = React.useState<{
    status: number | null;
    ms: number;
  } | null>(null);
  const [failure, setFailure] = React.useState<string | null>(null);
  const lineRef = React.useRef<HTMLSpanElement>(null);
  const beadRef = React.useRef<HTMLSpanElement>(null);
  const hostRef = React.useRef<HTMLSpanElement>(null);
  const wrapRef = React.useRef<HTMLDivElement>(null);

  if (!events.includes(event)) {
    setEvent(events[0] ?? "");
  }

  React.useEffect(() => {
    if (autoFocus)
      wrapRef.current
        ?.querySelector<HTMLButtonElement>("button[data-send]")
        ?.focus({ preventScroll: true });
  }, [autoFocus]);

  const send = async () => {
    if (status === "pending" || !event) return;
    setStatus("pending");
    setFailure(null);
    const answer = onSend(event);
    const bead = beadRef.current;
    const line = lineRef.current;
    const far = line ? Math.max(0, line.offsetWidth - 7) : 0;
    let ping: Animation | undefined;
    if (bead && !reduced) {
      bead.style.background = "var(--primary)";
      await bead
        .animate(
          [
            { transform: "translateX(0px)", opacity: 0 },
            { opacity: 1, offset: 0.12 },
            { transform: `translateX(${far}px)`, opacity: 1 },
          ],
          { duration: 620, easing: TRAVEL, fill: "forwards" },
        )
        .finished.catch(() => {});
      ping = hostRef.current?.animate(
        [
          {
            boxShadow:
              "inset 0 0 0 1px var(--border), 0 0 0 0px color-mix(in oklab, var(--primary) 35%, transparent)",
          },
          { boxShadow: "inset 0 0 0 1px var(--border), 0 0 0 6px transparent" },
        ],
        {
          duration: 900,
          iterations: Infinity,
          easing: "ease-out",
        },
      );
    }
    try {
      const d = await answer;
      ping?.cancel();
      const tone = toneFor(d.status);
      if (bead && !reduced) {
        bead.style.background = COLOR[tone];
        await bead
          .animate(
            [
              { transform: `translateX(${far}px)`, opacity: 1 },
              { transform: "translateX(0px)", opacity: 1, offset: 0.88 },
              { transform: "translateX(0px)", opacity: 0 },
            ],
            { duration: 640, easing: TRAVEL, fill: "forwards" },
          )
          .finished.catch(() => {});
      }
      setResult({ status: d.status, ms: Math.round(d.durationMs ?? 0) });
      setStatus(tone === "emerald" ? "success" : "error");
      onDelivered?.(d);
    } catch (e) {
      ping?.cancel();
      bead?.getAnimations().forEach((a) => a.cancel());
      setFailure(
        e instanceof Error && e.message
          ? e.message
          : "The test couldn't be sent.",
      );
      setStatus("error");
    }
  };

  const tone = result ? toneFor(result.status) : null;
  return (
    <div ref={wrapRef}>
      <div className="flex flex-wrap items-center gap-2">
        <PillSelect
          label="Event to send"
          mono
          options={events.map((ev) => ({ value: ev, label: ev }))}
          value={event}
          onValueChange={setEvent}
          width={260}
        />
        <StatusButton
          data-send=""
          size="sm"
          variant="outline"
          status={status}
          labels={{
            idle: "Send test",
            pending: "Sending",
            success: "Delivered",
            error: "Send again",
          }}
          onClick={send}
          onReset={() => setStatus("idle")}
          resetAfter={2200}
        />
      </div>

      {/* The wire: your app, the thin line, the endpoint. */}
      <div
        aria-hidden="true"
        className="mt-3 flex items-center gap-2 font-mono text-[11px]"
      >
        <span className="shrink-0 rounded-full px-2 py-0.5 text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]">
          {from}
        </span>
        <span ref={lineRef} className="relative h-px min-w-6 flex-1 bg-border">
          <span
            ref={beadRef}
            className="absolute -top-[3px] left-0 size-[7px] rounded-full opacity-0 will-change-transform"
          />
        </span>
        <span
          ref={hostRef}
          className="max-w-[55%] shrink truncate rounded-full px-2 py-0.5 text-foreground shadow-[inset_0_0_0_1px_var(--border)]"
        >
          {host}
        </span>
      </div>

      <div
        className="grid"
        style={{
          gridTemplateRows: result || failure ? "1fr" : "0fr",
          opacity: result || failure ? 1 : 0,
          transition: reduced
            ? "none"
            : `grid-template-rows 380ms ${EASE}, opacity 260ms ${EASE}`,
        }}
      >
        <div className="min-h-0 min-w-0 overflow-clip">
          <p
            role="status"
            className={`flex flex-wrap items-baseline gap-x-1 pt-2 text-[12px] tabular-nums ${failure ? TEXT.red : tone ? TEXT[tone] : "text-muted-foreground"}`}
          >
            {failure ? (
              failure
            ) : result ? (
              <>
                {result.status !== null && (
                  <NumberRoll
                    value={result.status}
                    className="font-mono font-medium"
                  />
                )}
                <TextMorph>{reasonFor(result.status)}</TextMorph>
                <span className="text-muted-foreground">in</span>
                <span className="inline-flex items-baseline text-muted-foreground">
                  <NumberRoll
                    value={result.ms}
                    format={{ maximumFractionDigits: 0 }}
                  />
                  &nbsp;ms
                </span>
              </>
            ) : null}
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * PILL SELECT: a select that's the same surface as its pill
 *
 *   open      the pill grows into its list (size and corners
 *             ease) from the edge it's lined up with, while its
 *             label fades into the options; it opens upward when
 *             there's no room below, and long lists scroll
 *   pick      the list folds back into the pill and the label
 *             morphs to the new choice; the current option
 *             carries a drawn check
 *   keys      arrows move a highlight that glides between rows,
 *             Home and End jump, typing a few letters finds an
 *             option, Enter picks, Escape folds it back
 *
 * The list lives in a portal on the page's body, placed over
 * the pill, so a clipping toolbar, fold or scroller never cuts
 * it off; it carries the theme's colours with it. Scrolling
 * the page closes it.
 *
 * Used wherever a component needs a choice from a list; never
 * the browser's own dropdown, which can't follow the theme.
 * ───────────────────────────────────────────────────────── */

export interface PillOption {
  value: string;
  label: string;
  /** A second line in the list, e.g. a sample value. */
  description?: string;
}

export interface PillSelectProps {
  options: PillOption[];
  value: string | null | undefined;
  onValueChange: (value: string) => void;
  /** Accessible name, e.g. "Column for Email". */
  label: string;
  /** Shown while nothing is chosen. */
  placeholder?: string;
  /** What the pill shows for a choice; the option's label by default. */
  display?: (option: PillOption | undefined) => string;
  /** The pill's contents, when it needs more than text (an icon that turns). */
  renderValue?: (
    option: PillOption | undefined,
    open: boolean,
  ) => React.ReactNode;
  /** Monospace labels, for code-like values (event names, column headers). */
  mono?: boolean;
  /** Which edge of the pill the list lines up with. */
  align?: "start" | "end";
  /** The list's width; never narrower than the pill. */
  width?: number;
  /** Fill the width it's given. */
  block?: boolean;
  /** Dims the pill's text, e.g. for "Don't import". */
  muted?: boolean;
  disabled?: boolean;
  /** "sm" is the 28px pill for toolbars; "md" is 36px, the height of the other form fields. */
  size?: "sm" | "md";
  className?: string;
}

type Phase = "closed" | "opening" | "open" | "closing";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DURATION = 420;
const MAX_LIST = 280;
const PILL_SIZE = {
  sm: "h-7 px-2.5 text-[12px]",
  md: "h-9 pl-4 pr-3.5 text-[13.5px]",
};
// The theme travels with the list, so it matches the pill wherever the pill's colours were set.
const TOKENS = [
  "--background",
  "--foreground",
  "--popover",
  "--popover-foreground",
  "--border",
  "--accent",
  "--accent-foreground",
  "--primary",
  "--primary-foreground",
  "--muted",
  "--muted-foreground",
  "--ring",
];
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Chevron({ up, reduced }: { up: boolean; reduced: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3 shrink-0 text-muted-foreground"
      style={{
        transform: up ? "rotate(180deg)" : "none",
        transition: reduced ? "none" : `transform 320ms ${EASE}`,
      }}
    >
      <path
        d="M4.5 6.25 8 9.75l3.5-3.5"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function PillSelect({
  options,
  value,
  onValueChange,
  label,
  placeholder = "Choose",
  display,
  renderValue,
  mono = false,
  align = "start",
  width = 240,
  block = false,
  muted = false,
  disabled = false,
  size = "sm",
  className = "",
}: PillSelectProps) {
  const id = React.useId();
  const reduced = useReducedMotion();
  const [phase, setPhase] = React.useState<Phase>("closed");
  const [active, setActive] = React.useState(0);
  const [pill, setPill] = React.useState({ width: 0, height: 28 });
  const [panelHeight, setPanelHeight] = React.useState(0);
  const [fit, setFit] = React.useState({
    up: false,
    width,
    shift: 0,
    x: 0,
    y: 0,
    theme: {} as Record<string, string>,
  });
  const [highlight, setHighlight] = React.useState({
    top: 0,
    height: 0,
    ready: false,
  });
  const [quiet, setQuiet] = React.useState(false);
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const surfaceRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const rowRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const timer = React.useRef(0);
  const typed = React.useRef({ text: "", at: 0 });
  const selected = options.find((o) => o.value === value);
  const expanded = phase === "open";
  const mounted = phase !== "closed";
  const [prevPhase, setPrevPhase] = React.useState(phase);
  if (phase !== prevPhase) {
    setPrevPhase(phase);
    if (phase === "closed") {
      setHighlight({ top: 0, height: 0, ready: false });
    }
  }
  const text = display ? display(selected) : (selected?.label ?? placeholder);

  const measureFit = () => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const rect = wrap.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const w = Math.min(Math.max(width, rect.width), vw - 24);
    // Lined up with the pill's edge, nudged back on screen.
    const shift =
      align === "start"
        ? Math.min(0, vw - 12 - (rect.left + w))
        : Math.max(0, 12 - (rect.right - w));
    const estimate =
      Math.min(
        MAX_LIST,
        options.length * (options.some((o) => o.description) ? 46 : 32),
      ) + 12;
    const vh = window.innerHeight;
    const below = vh - 8 - rect.top;
    const above = rect.bottom - 8;
    const up = below < estimate + 8 && above > below;
    // Fixed coordinates of the pill's corner the list grows from.
    const x = align === "start" ? rect.left : vw - rect.right;
    const y = up ? vh - rect.bottom : rect.top;
    const cs = getComputedStyle(wrap);
    const theme: Record<string, string> = {
      colorScheme: cs.colorScheme,
      fontFamily: cs.fontFamily,
    };
    for (const t of TOKENS) {
      const v = cs.getPropertyValue(t);
      if (v) theme[t] = v;
    }
    setFit({ up, width: w, shift, x, y, theme });
  };

  const open = () => {
    if (disabled || phase === "open" || phase === "opening") return;
    window.clearTimeout(timer.current);
    measureFit();
    setActive(
      Math.max(
        0,
        options.findIndex((o) => o.value === value),
      ),
    );
    setPhase(reduced ? "open" : "opening");
  };

  const close = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) triggerRef.current?.focus({ preventScroll: true });
      if (reduced) return setPhase("closed");
      setPhase("closing");
      timer.current = window.setTimeout(() => setPhase("closed"), DURATION);
    },
    [reduced],
  );

  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setPhase("open"))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  React.useLayoutEffect(() => {
    const trigger = triggerRef.current;
    if (!trigger) return;
    const measure = () =>
      setPill((p) =>
        p.width === trigger.offsetWidth && p.height === trigger.offsetHeight
          ? p
          : { width: trigger.offsetWidth, height: trigger.offsetHeight },
      );
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(trigger);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const panel = panelRef.current;
    if (panel) setPanelHeight(panel.offsetHeight);
  }, [mounted, options]);

  // The highlight glides to the active row, and the list scrolls to keep it in view.
  React.useLayoutEffect(() => {
    const row = rowRefs.current[active];
    const list = listRef.current;
    if (!row || !list) return;
    setHighlight((h) =>
      h.top === row.offsetTop &&
      h.height === row.offsetHeight &&
      h.ready === (h.ready || expanded)
        ? h
        : {
            top: row.offsetTop,
            height: row.offsetHeight,
            ready: h.ready || expanded,
          },
    );
    const scroller = list.parentElement;
    if (scroller && scroller.scrollHeight > scroller.clientHeight) {
      if (row.offsetTop < scroller.scrollTop)
        scroller.scrollTop = row.offsetTop - 4;
      else if (
        row.offsetTop + row.offsetHeight >
        scroller.scrollTop + scroller.clientHeight
      )
        scroller.scrollTop =
          row.offsetTop + row.offsetHeight - scroller.clientHeight + 4;
    }
  }, [active, expanded, mounted]);

  React.useEffect(() => {
    if (expanded) listRef.current?.focus({ preventScroll: true });
  }, [expanded]);

  React.useEffect(() => {
    if (!expanded) return;
    const inside = (n: Node) =>
      Boolean(wrapRef.current?.contains(n) || surfaceRef.current?.contains(n));
    const onDown = (e: PointerEvent) => {
      if (!inside(e.target as Node)) close(false);
    };
    // The list sits where the pill was; if the page moves under it, it goes at once rather than fold in the wrong place.
    const gone = () => {
      window.clearTimeout(timer.current);
      setPhase("closed");
    };
    const onScroll = (e: Event) => {
      if (!surfaceRef.current?.contains(e.target as Node)) gone();
    };
    const onResize = gone;
    document.addEventListener("pointerdown", onDown);
    window.addEventListener("scroll", onScroll, true);
    window.addEventListener("resize", onResize);
    return () => {
      document.removeEventListener("pointerdown", onDown);
      window.removeEventListener("scroll", onScroll, true);
      window.removeEventListener("resize", onResize);
    };
  }, [expanded, close]);

  const choose = (o: PillOption) => {
    close();
    if (o.value !== value) onValueChange(o.value);
  };

  const onListKey = (e: React.KeyboardEvent) => {
    const last = options.length - 1;
    const move = (to: number) => {
      e.preventDefault();
      setActive(Math.max(0, Math.min(last, to)));
    };
    if (e.key === "ArrowDown") move(active === last ? 0 : active + 1);
    else if (e.key === "ArrowUp") move(active === 0 ? last : active - 1);
    else if (e.key === "Home") move(0);
    else if (e.key === "End") move(last);
    else if (e.key === "PageDown") move(active + 6);
    else if (e.key === "PageUp") move(active - 6);
    else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (options[active]) choose(options[active]);
    } else if (e.key === "Tab") close(false);
    else if (e.key.length === 1 && /\S/.test(e.key)) {
      // A few letters typed quickly find the option that starts with them.
      const now = performance.now();
      typed.current = {
        text:
          (now - typed.current.at < 700 ? typed.current.text : "") +
          e.key.toLowerCase(),
        at: now,
      };
      const hit = options.findIndex((o) =>
        o.label.toLowerCase().startsWith(typed.current.text),
      );
      if (hit !== -1) setActive(hit);
    }
  };

  const w = expanded ? fit.width : pill.width;
  const h = expanded ? panelHeight : pill.height;
  const listId = `${id}-list`;
  const pillText = renderValue ? null : (
    <>
      <span
        className={`min-w-0 flex-1 truncate text-left ${mono ? "font-mono text-[11.5px]" : ""} ${muted || !selected ? "text-muted-foreground" : "text-foreground"}`}
      >
        {block ? text : <TextMorph>{text}</TextMorph>}
      </span>
      <Chevron up={expanded} reduced={reduced} />
    </>
  );

  return (
    <div
      ref={wrapRef}
      className={`relative ${block ? "flex w-full min-w-0" : "inline-flex"} ${className}`}
      onKeyDown={(e) => {
        setQuiet(false);
        if (e.key === "Escape" && expanded) {
          e.preventDefault();
          e.stopPropagation();
          close();
        }
      }}
      onBlur={(e) => {
        const to = e.relatedTarget as Node | null;
        if (
          expanded &&
          document.hasFocus() &&
          !(
            to &&
            (wrapRef.current?.contains(to) || surfaceRef.current?.contains(to))
          )
        )
          close(false);
      }}
    >
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={expanded}
        aria-controls={mounted ? listId : undefined}
        aria-label={`${label}: ${selected?.label ?? placeholder}`}
        disabled={disabled}
        onClick={() => (expanded ? close() : open())}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown" || e.key === "ArrowUp") {
            e.preventDefault();
            open();
          }
        }}
        onPointerDown={() => setQuiet(true)}
        className={`inline-flex ${PILL_SIZE[size]} min-w-0 cursor-pointer items-center gap-1.5 rounded-full font-medium whitespace-nowrap shadow-[inset_0_0_0_1px_var(--border)] transition-colors duration-150 hover:bg-accent disabled:cursor-default disabled:opacity-50 disabled:hover:bg-transparent ${block ? "w-full" : ""} ${quiet ? "outline-none" : FOCUS}`}
      >
        {renderValue ? renderValue(selected, expanded) : pillText}
      </button>

      {mounted &&
        createPortal(
          <div
            ref={surfaceRef}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                e.preventDefault();
                e.stopPropagation();
                close();
              }
            }}
            onPointerDown={(e) => {
              if (!(e.target as HTMLElement).closest("[data-scroll]"))
                e.preventDefault();
              setQuiet(true);
            }}
            className="fixed z-[60] overflow-hidden bg-popover text-popover-foreground"
            style={{
              ...fit.theme,
              [fit.up ? "bottom" : "top"]: fit.y,
              [align === "start" ? "left" : "right"]:
                fit.x +
                (expanded ? (align === "start" ? fit.shift : -fit.shift) : 0),
              width: w,
              height: h,
              borderRadius: expanded ? 16 : pill.height / 2,
              // The pill's own cavemio, the whole way: it is the same surface.
              boxShadow: "inset 0 0 0 1px var(--border)",
              transition: reduced
                ? "none"
                : `width ${DURATION}ms ${EASE}, height ${DURATION}ms ${EASE}, left ${DURATION}ms ${EASE}, right ${DURATION}ms ${EASE}, border-radius ${DURATION}ms ${EASE}`,
            }}
          >
            {/* The pill's label, fading out as the surface grows and back in as it folds. */}
            <span
              aria-hidden="true"
              className={`pointer-events-none absolute inline-flex ${PILL_SIZE[size]} items-center gap-1.5 font-medium whitespace-nowrap ${fit.up ? "bottom-0" : "top-0"} ${align === "start" ? "left-0" : "right-0"}`}
              style={{
                width: pill.width,
                opacity: expanded ? 0 : 1,
                transition: reduced
                  ? "none"
                  : `opacity ${expanded ? 120 : 260}ms ${EASE} ${expanded ? 0 : 120}ms`,
              }}
            >
              {renderValue ? renderValue(selected, expanded) : pillText}
            </span>
            <div
              ref={panelRef}
              className={`absolute p-1 ${fit.up ? "bottom-0" : "top-0"} ${align === "start" ? "left-0" : "right-0"}`}
              style={{
                width: fit.width,
                opacity: expanded ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `opacity ${expanded ? 260 : 120}ms ${EASE} ${expanded ? 90 : 0}ms`,
              }}
            >
              <div
                data-scroll=""
                className="overflow-y-auto overscroll-contain"
                style={{ maxHeight: MAX_LIST }}
              >
                <div
                  ref={listRef}
                  id={listId}
                  role="listbox"
                  tabIndex={-1}
                  aria-label={label}
                  aria-activedescendant={`${id}-o${active}`}
                  onKeyDown={onListKey}
                  className="relative outline-none"
                >
                  <span
                    aria-hidden="true"
                    className="pointer-events-none absolute inset-x-0 top-0 rounded-[12px] bg-accent"
                    style={{
                      height: highlight.height,
                      transform: `translateY(${highlight.top}px)`,
                      opacity: highlight.ready ? 1 : 0,
                      transition:
                        highlight.ready && !reduced
                          ? `transform 260ms ${EASE}, height 260ms ${EASE}, opacity 200ms`
                          : "none",
                    }}
                  />
                  {options.map((o, i) => {
                    const on = o.value === value;
                    return (
                      <div
                        key={o.value}
                        ref={(el) => {
                          rowRefs.current[i] = el;
                        }}
                        id={`${id}-o${i}`}
                        role="option"
                        aria-selected={on}
                        onPointerMove={() => setActive(i)}
                        onClick={() => choose(o)}
                        className="relative flex cursor-pointer items-start gap-2 rounded-[12px] px-2.5 py-1.5"
                      >
                        <span className="min-w-0 flex-1">
                          <span
                            className={`block truncate ${mono ? "font-mono text-[12px]" : "text-[12.5px] font-medium"}`}
                          >
                            {o.label}
                          </span>
                          {o.description && (
                            <span className="mt-0.5 block truncate text-[11.5px] text-muted-foreground">
                              {o.description}
                            </span>
                          )}
                        </span>
                        <svg
                          viewBox="0 0 16 16"
                          fill="none"
                          aria-hidden="true"
                          className="mt-0.5 size-3.5 shrink-0"
                        >
                          <path
                            d="M3.5 8.5 6.5 11.5 12.5 4.5"
                            stroke="currentColor"
                            strokeWidth="1.8"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            pathLength={1}
                            strokeDasharray={1}
                            style={{
                              strokeDashoffset: on && expanded ? 0 : 1,
                              transition: reduced
                                ? "none"
                                : `stroke-dashoffset 380ms ${EASE} 160ms`,
                            }}
                          />
                        </svg>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>,
          document.body,
        )}
    </div>
  );
}

